<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>RentFlow</title><style>body{font-family:system-ui;background:#f3f6f4;color:#15231b;margin:0}.wrap{max-width:1050px;margin:auto;padding:32px}.top{display:flex;justify-content:space-between;align-items:center}.brand{font-weight:800;font-size:24px;color:#0d7a47}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:white;border-radius:16px;padding:20px;box-shadow:0 4px 20px #15352212}.num{font-size:30px;font-weight:800}table{width:100%;border-collapse:collapse}td,th{padding:12px;text-align:left;border-bottom:1px solid #e5ebe7}.pill{padding:5px 9px;border-radius:12px;background:#e5f5ec}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="top"><div class="brand">RentFlow</div><div>Owner dashboard</div></div><h1>Atlas Drive Rental</h1><div class="grid"><div class="card"><div>Bookings</div><div class="num" id="bookings">—</div></div><div class="card"><div>Potential revenue</div><div class="num" id="potential">—</div></div><div class="card"><div>Confirmed revenue</div><div class="num" id="confirmed">—</div></div></div><div class="card" style="margin-top:16px"><h2>Latest booking requests</h2><table><thead><tr><th>Customer</th><th>Vehicle</th><th>Dates</th><th>Total</th><th>Status</th></tr></thead><tbody id="rows"></tbody></table></div></div><script>fetch('/api/dashboard/stats').then(r=>r.json()).then(d=>{bookings.textContent=d.stats.bookings;potential.textContent=d.stats.potential_revenue+' MAD';confirmed.textContent=d.stats.confirmed_revenue+' MAD';rows.innerHTML=d.latest.map(x=>`<tr><td>${x.customer_name}</td><td>${x.make} ${x.model}</td><td>${x.pickup_date} → ${x.return_date}</td><td>${x.total} MAD</td><td><span class="pill">${x.status}</span></td></tr>`).join('')}).catch(()=>{});</script></body></html>

